const pptxgen = require("pptxgenjs");

const NAVY = "2F3C7E";
const CHERRY = "990011";
const OFFWHITE = "FCF6F5";
const TEXT_DARK = "241B1B";
const MUTED = "6B6560";
const WHITE = "FFFFFF";

const HEADER_FONT = "Cambria";
const BODY_FONT = "Calibri";

function newPres() {
  const pres = new pptxgen();
  pres.defineLayout({ name: "WIDE", width: 13.333, height: 7.5 });
  pres.layout = "WIDE";
  return pres;
}

const pres = newPres();

